public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0) throw new IllegalArgumentException("n must be positive");
    if (edges == null || edges.length != n-1) throw new IllegalArgumentException("edges length must be n-1");
    if (hasApple == null || hasApple.length != n) throw new IllegalArgumentException("hasApple length must be n");
    // build adjacency
    List<Integer>[] adj = new ArrayList[n];
    for (int i=0;i<n;i++) adj[i] = new ArrayList<>();
    for (int[] e: edges) {
        if (e==null || e.length!=2) throw new IllegalArgumentException("edge must have two nodes");
        int u=e[0], v=e[1];
        if (u<0||u>=n||v<0||v>=n) throw new IllegalArgumentException("edge node out of bounds");
        adj[u].add(v);
        adj[v].add(u);
    }
    int[] parent = new int[n];
    Arrays.fill(parent, -1);
    int[] order = new int[n];
    int idx=0;
    // stack for DFS
    int[] stack = new int[n];
    int top=0;
    stack[top++] = 0;
    parent[0] = -2; // root marker
    while (top>0) {
        int node = stack[--top];
        order[idx++] = node;
        for (int nei: adj[node]) {
            if (parent[nei]==-1) {
                parent[nei] = node;
                stack[top++] = nei;
            }
        }
